from __future__ import annotations


def o(value: str, label: str, score: int | None) -> dict:
    return {"value": value, "label": label, "score": score}


def q(key: str, label: str, options: list[dict], help: str | None = None) -> dict:
    item = {"key": key, "label": label, "options": options}
    if help:
        item["help"] = help
    return item


def factor(key: str, name: str, questions: list[dict], informational: bool = False) -> dict:
    return {"key": key, "name": name, "questions": questions, "informational": informational}


def module(key: str, name: str, description: str, factors: list[dict]) -> dict:
    return {"key": key, "name": name, "weight": 20, "description": description, "factors": factors}


